#include <Wire.h>

const int MPU = 0x68;
long offset = 0;

void wake() {
  Wire.beginTransmission(MPU);
  Wire.write(0x6B);
  Wire.write(0);
  Wire.endTransmission();
}

int16_t readGx() {
  Wire.beginTransmission(MPU);
  Wire.write(0x43);     // GYRO_XOUT_H: 2 bytes of X rotation
  Wire.endTransmission(false);
  Wire.requestFrom(MPU, 2);
  return Wire.read() << 8 | Wire.read();
}

void setup() {
  Serial.begin(9600);
  Wire.begin();
  wake();
  delay(100);
  long sum = 0;
  for (int i = 0; i < 200; i++) {
    sum += readGx();
    delay(2);
  }
  offset = sum / 200;
  Serial.print("calibrated: offset ");
  Serial.print(offset);
  Serial.println(" counts");
}

void loop() {
  float gx = (readGx() - offset) / 131.0;
  Serial.print("gx ");
  Serial.print(gx, 2);
  Serial.println(" deg/s");
  delay(500);
}

